// Some portions generated by Codex
type LanguageLiteralMetadata = {
  language?: string;
  direction?: "ltr" | "rtl";
};

/** The browser's base-direction attribute and the language metadata shown beside an RDF language literal. */
export function languageLiteralPresentation({ language, direction }: LanguageLiteralMetadata) {
  return {
    dir: direction,
    languageLabel: language ? `${language}${direction ? `--${direction}` : ""}` : undefined,
  };
}
